import { readFileSync } from 'node:fs';
import { describe, it, expect } from 'vitest';
import {
  parseStandardCode,
  buildNormalizedCode,
  buildBaseKey,
  expandParsedCode,
  type ParsedStandardCode
} from '../src/standards/code-parser.js';

// Golden fixtures are generated by running the ORIGINAL Python parser
// (parse_data/src/parsers/std_code_parser.py) — see
// tests/fixtures/generate-golden.py. Do not hand-edit the JSON.
// Cases with a `divergence` marker are intentional TS-only fixes
// (user decision 2026-11-23): TS must match Python on every field
// except those listed in divergence.ts_fields, which must equal the
// stated TS values. The shared LIGHT-normalization fixture
// (code-normalize-shared.json, generated by generate-shared.ts) is
// tested in tests/light-normalize.test.ts — the full parser no longer
// decides normalized_code (user decision 2026-11-23).

interface GoldenCase {
  input: string;
  expected: Record<string, unknown>;
  divergence?: { reason: string; ts_fields: Record<string, unknown> };
}

const golden = JSON.parse(
  readFileSync(new URL('./fixtures/code-parser-golden.json', import.meta.url), 'utf8')
) as GoldenCase[];

// Round numbers to 6dp and map undefined -> null so float representation
// noise (Python Decimal -> JSON float vs JS number) cannot fail a case.
function normalizeForCompare(value: unknown): unknown {
  if (value === undefined) return null;
  if (typeof value === 'number') return Math.round(value * 1e6) / 1e6;
  if (Array.isArray(value)) return value.map(normalizeForCompare);
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([k, v]) => [
        k,
        normalizeForCompare(v)
      ])
    );
  }
  return value;
}

describe('parseStandardCode — golden đối chiếu Python gốc', () => {
  it(`khớp từng trường trên ${golden.length} mã mẫu (trừ case divergence có chủ ý)`, () => {
    const mismatches: string[] = [];
    for (const { input, expected, divergence } of golden) {
      const actual = parseStandardCode(input) as unknown as Record<string, unknown>;
      const expectedKeys = Object.keys(expected).sort();
      const actualKeys = Object.keys(actual).sort();
      if (JSON.stringify(expectedKeys) !== JSON.stringify(actualKeys)) {
        mismatches.push(
          `${JSON.stringify(input)}: keys expected [${expectedKeys}] got [${actualKeys}]`
        );
        continue;
      }
      for (const key of expectedKeys) {
        const expRaw =
          divergence && key in divergence.ts_fields ? divergence.ts_fields[key] : expected[key];
        const exp = normalizeForCompare(expRaw);
        const act = normalizeForCompare(actual[key]);
        if (JSON.stringify(exp) !== JSON.stringify(act)) {
          mismatches.push(
            `${JSON.stringify(input)}.${key}: expected ${JSON.stringify(exp)} got ${JSON.stringify(act)}`
          );
        }
      }
    }
    expect(mismatches).toEqual([]);
  });

  it('mọi case divergence đều có lý do và chỉ lệch ở các trường đã khai', () => {
    const divergent = golden.filter((c) => c.divergence);
    expect(divergent.length).toBeGreaterThan(0);
    for (const { input, divergence } of divergent) {
      expect(divergence?.reason.length, JSON.stringify(input)).toBeGreaterThan(10);
      expect(Object.keys(divergence?.ts_fields ?? {}).length).toBeGreaterThan(0);
    }
  });
});

describe('buildNormalizedCode (parser — chỉ còn điền cột tùy chọn, không quyết định khóa)', () => {
  it('trả null khi mã không parse được (không bịa khóa)', () => {
    for (const { input, expected } of golden) {
      const parsed: ParsedStandardCode = parseStandardCode(input);
      if (expected['std_main_number'] === null) {
        expect(buildNormalizedCode(parsed), JSON.stringify(input)).toBeNull();
        expect(buildBaseKey(parsed), JSON.stringify(input)).toBeNull();
        expect(expandParsedCode(parsed), JSON.stringify(input)).toEqual([]);
      }
    }
  });
});

describe('normalized_code dựng từ org_prefix (quyết định 2026-11-23)', () => {
  const keyOf = (code: string) => buildNormalizedCode(parseStandardCode(code));

  it('designation khác nhau → khóa khác nhau (không gộp adoption)', () => {
    const keys = [
      keyOf('ISO 9001:2015'),
      keyOf('EN ISO 9001:2015'),
      keyOf('BS EN ISO 9001:2015'),
      keyOf('TCVN ISO 9001:2015')
    ];
    expect(keys).toEqual([
      'ISO9001:2015',
      'ENISO9001:2015',
      'BSENISO9001:2015',
      'TCVNISO9001:2015'
    ]);
    expect(new Set(keys).size).toBe(4);
  });

  it('cùng designation viết nhiều kiểu → cùng khóa', () => {
    const variants = ['TCVN9386-1:2012', 'tcvn 9386-1:2012', 'TCVN 9386-1:2012'];
    const keys = variants.map(keyOf);
    expect(new Set(keys).size).toBe(1);
    expect(keys[0]).toBe('TCVN9386-1:2012');
  });

  it('GB/T giữ dấu / và khác GB trần', () => {
    expect(keyOf('GB/T 19001-2016')).toBe('GB/T19001:2016');
    expect(keyOf('GB 19001-2016')).toBe('GB19001:2016');
  });

  it('base_key bỏ năm và suffix', () => {
    const parsed = parseStandardCode('TCVN 9386-1:2012');
    expect(buildBaseKey(parsed)).toBe('TCVN9386-1');
    const amended = parseStandardCode('ISO 9001:2015/Amd 1:2016');
    expect(buildBaseKey(amended)).toBe('ISO9001');
  });
});

describe('amendment/corrigendum (sửa ở bản TS, chủ ý khác Python)', () => {
  const keyOf = (code: string) => buildNormalizedCode(parseStandardCode(code));

  it('"Amd 1:2016" có khoảng trắng vẫn giữ amendment và không trùng khóa bản gốc', () => {
    const parsed = parseStandardCode('ISO 9001:2015/Amd 1:2016');
    expect(parsed.amendment).toBe('AMD1:2016');
    expect(parsed.suffix).toBe('AMD1:2016');
    expect(keyOf('ISO 9001:2015/Amd 1:2016')).toBe('ISO9001:2015/AMD1:2016');
    expect(keyOf('ISO 9001:2015/Amd 1:2016')).not.toBe(keyOf('ISO 9001:2015'));
  });

  it('dạng không khoảng trắng và có khoảng trắng cho cùng khóa', () => {
    expect(keyOf('ISO 9001:2015/AMD1:2016')).toBe(keyOf('ISO 9001:2015/Amd 1:2016'));
    expect(keyOf('ISO 9001:2015/COR1:2019')).toBe(keyOf('ISO 9001:2015/Cor 1:2019'));
  });

  it('phần dư không parse được không trùng khóa với bản gốc', () => {
    const withProse = keyOf('TCVN 9143:2022 GHI CHU');
    expect(withProse).not.toBeNull();
    expect(withProse).not.toBe(keyOf('TCVN 9143:2022'));
  });
});

describe('expandParsedCode — expanded_parts=null thì một bản ghi duy nhất', () => {
  it('khoảng vượt guard giữ chuỗi phần thô, không tự tách, confidence thấp', () => {
    const parsed = parseStandardCode('TCVN 1234-1 đến 200:2020');
    expect(parsed.parts_kind).toBe('range');
    expect(parsed.expanded_parts).toBeNull();
    expect(parsed.std_parts).toEqual(['1', '200']);
    const records = expandParsedCode(parsed);
    expect(records).toHaveLength(1);
    expect(records[0].part).toBe('1-200');
    expect(records[0].normalized_code).toBe('TCVN1234-1-200:2020');
    expect(records[0].parse_confidence).toBeLessThanOrEqual(0.5);
  });

  it('khoảng hợp lệ tách một bản ghi mỗi phần, giữ năm từng phần', () => {
    const records = expandParsedCode(parseStandardCode('BS EN 13146-1 đến 3:2019'));
    expect(records.map((r) => r.normalized_code)).toEqual([
      'BSEN13146-1:2019',
      'BSEN13146-2:2019',
      'BSEN13146-3:2019'
    ]);
    expect(records.map((r) => r.base_key)).toEqual([
      'BSEN13146-1',
      'BSEN13146-2',
      'BSEN13146-3'
    ]);
  });
});
